// Numerical tools for PPT 32–47. All rates have explicit surface/reservoir bases.
import {splitData} from '../agent/core.mjs';
export const avg=a=>a.length?a.reduce((s,v)=>s+Number(v),0)/a.length:0;
const numeric=(v,label)=>{if(v===null||v===undefined||String(v).trim()===''||!Number.isFinite(Number(v)))throw Error(label+'必须为有限数值');return Number(v);};
const nonnegative=(v,label)=>{v=numeric(v,label);if(v<0)throw Error(label+'必须非负');return v;};
export function balance(r){const I=nonnegative(r.injection,'注水量'),O=nonnegative(r.oil,'产油量'),W=nonnegative(r.water,'产水量');const Bo=numeric(r.Bo??1,'原油体积系数'),Bw=numeric(r.Bw??1,'水体积系数');if(Bo<=0||Bw<=0)throw Error('体积系数必须为正');const denominator=O*Bo+W*Bw;if(!denominator)throw Error('采出体积不能为零');const ratio=I*Bw/denominator,trend=Number(r.pressure_trend??0);return {ratio,pressureRetention:r.initial_pressure?Number(r.pressure)/Number(r.initial_pressure):null,state:ratio<.9&&trend<0?'亏空':ratio>1.1&&trend>0?'过量':ratio>=.9&&ratio<=1.1&&Math.abs(trend)<=.1?'平衡':'需联合研判',basis:r.Bo===undefined||r.Bw===undefined?'地面体积近似（缺PVT）':'油水两相地下体积（未计游离气）'};}
export function layerSplit(layers,total){total=nonnegative(total,'总量');if(!layers.length)throw Error('缺少小层属性');const a=layers.map(l=>({...l,capacity:nonnegative(l.permeability,'渗透率')*nonnegative(l.thickness,'厚度')*nonnegative(l.connectivity??1,'连通系数')}));const sum=a.reduce((s,l)=>s+l.capacity,0);if(!sum)throw Error('小层总吸水能力为零');return a.map(l=>({...l,fraction:l.capacity/sum,volume:total*l.capacity/sum,intensity:l.thickness?total*l.capacity/sum/l.thickness:null}));}
export function correlation(x,y){const mx=avg(x),my=avg(y);let a=0,b=0,c=0;for(let i=0;i<x.length;i++){a+=(x[i]-mx)*(y[i]-my);b+=(x[i]-mx)**2;c+=(y[i]-my)**2;}return b*c?a/Math.sqrt(b*c):0;}
export function lagCorrelation(x,y,maxLag=30){if(x.length!==y.length||x.length<8)throw Error('需至少8条同期注采数据');let best={lag:0,correlation:-Infinity},curve=[];for(let lag=0;lag<=Math.min(maxLag,x.length-5);lag++){const c=correlation(x.slice(0,x.length-lag),y.slice(lag));curve.push({lag,correlation:c});if(c>best.correlation)best={lag,correlation:c};}return {...best,curve};}
export function allocate(layers,total){total=nonnegative(total,'供水总量');if(!layers.length)throw Error('缺少配注对象');const out=layers.map(l=>{const max=nonnegative(l.max,'配注上限'),min=nonnegative(l.min??0,'配注下限'),J=nonnegative(l.injectivity,'吸水指数'),p=numeric(l.pressure,'地层压力'),pf=numeric(l.fracture,'破裂压力');const capacity=Math.min(max,Math.max(0,(pf-p)*J));if(min>capacity)throw Error('约束不可行：'+l.id+'下限高于压力/设备容量');return {...l,capacity,target:min,weight:nonnegative(l.weight??1,'权重')};});if(out.reduce((s,l)=>s+l.target,0)>total+1e-9)throw Error('约束不可行：总供水不足以满足下限');let remain=total-out.reduce((s,l)=>s+l.target,0);for(let it=0;it<out.length+2&&remain>1e-9;it++){const a=out.filter(l=>l.capacity-l.target>1e-9&&l.weight>0),w=a.reduce((s,l)=>s+l.weight,0);if(!w)break;let used=0;for(const l of a){const v=Math.min(l.capacity-l.target,remain*l.weight/w);l.target+=v;used+=v;}remain-=used;}return out.map(l=>({...l,predictedPressure:l.injectivity?l.pressure+l.target/l.injectivity:l.pressure}));}
export function measureEffect(rows,cost,netOilPrice){cost=nonnegative(cost,'投入成本');netOilPrice=nonnegative(netOilPrice,'单位增油净收益');if(!rows.length)throw Error('缺少措施后实际生产记录');const incremental=rows.reduce((s,r)=>s+numeric(r.oil,'实际日产油')-numeric(r.baseline,'无措施基线'),0),revenue=incremental*netOilPrice,net=revenue-cost;return {days:rows.length,incremental,revenue,net,roi:cost?net/cost:null,payoutRatio:cost?revenue/cost:null};}
export function reserves(r){const qi=nonnegative(r.qi,'初始产油'),D=nonnegative(r.D,'递减率'),b=nonnegative(r.b,'递减指数'),days=Math.floor(numeric(r.days,'预测天数'));if(b>1||days<1||days>36500)throw Error('递减指数需0–1，预测天数需1–36500');const price=nonnegative(r.oilPrice,'油价'),waterCost=nonnegative(r.waterCost,'产水成本'),fixed=nonnegative(r.fixedCost,'固定成本'),wc=numeric(r.waterCut,'含水率');if(wc<0||wc>=1)throw Error('含水率应在0–1且小于1');let volume=0,net=0;const curve=[];for(let d=0;d<days;d++){const q=qi*(b===0?Math.exp(-D*d):(1+b*D*d)**(-1/b)),cash=q*price-q*wc/(1-wc)*waterCost-fixed;if(cash<=0)break;volume+=q;net+=cash;curve.push({day:d,oil:q,cash});}return {volume,net,effectiveDays:curve.length,curve};}
export function assertDisjoint(sets){const seen=new Set();for(const rs of sets)for(const r of rs){const k=r.test_id?`${r.test_id}@${r.time_min??r.sample_id}`:r.event_id??(r.sample_id!==undefined?`${r.well_id}@${r.sample_id}`:`${r.well_id}@${r.date}`);if(seen.has(k))throw Error('发现重复或跨集合重叠记录：'+k);seen.add(k);}}
export function partition(rows,ratios=[70,15,15],method='well-time'){if(ratios.some(r=>!Number.isFinite(Number(r))||r<=0)||Math.abs(ratios.reduce((s,v)=>s+Number(v),0)-100)>.0001)throw Error('训练、验证、测试比例必须为正且合计100%');assertDisjoint([rows]);const out=splitData(rows,ratios,method,42);if(out.some(x=>!x.length))throw Error('样本不足以划分三个非空集合');return out;}
export function rng(seed=42){let s=seed>>>0;return()=>((s=(Math.imul(s,1664525)+1013904223)>>>0)/4294967296);}
function tree(rows,keys,target,depth,random){const value=avg(rows.map(r=>r[target]));if(depth<=0||rows.length<6)return {value};let best=null;const base=rows.reduce((s,r)=>s+(r[target]-value)**2,0);for(const key of keys){const values=[...new Set(rows.map(r=>r[key]))].sort((a,b)=>a-b);const candidates=Array.from({length:Math.min(12,values.length-1)},(_,i)=>values[Math.floor((i+1)*values.length/(Math.min(12,values.length-1)+1))]);for(const cut of candidates){const left=rows.filter(r=>r[key]<=cut),right=rows.filter(r=>r[key]>cut);if(left.length<2||right.length<2)continue;const ml=avg(left.map(r=>r[target])),mr=avg(right.map(r=>r[target]));const error=left.reduce((s,r)=>s+(r[target]-ml)**2,0)+right.reduce((s,r)=>s+(r[target]-mr)**2,0);if(error<base&&(!best||error<best.error))best={key,cut,error,left,right};}}
 return best?{key:best.key,cut:best.cut,left:tree(best.left,keys,target,depth-1,random),right:tree(best.right,keys,target,depth-1,random)}:{value};}
const leaf=(t,r)=>t.value!==undefined?t.value:leaf(r[t.key]<=t.cut?t.left:t.right,r);
function validRows(rows,keys,target){if(rows.length<8)throw Error('至少8条有效训练记录');for(const r of rows)for(const k of [...keys,...(target?[target]:[])])numeric(r[k],k);}
export function trainTrees(id,rows,keys,target,options={}){validRows(rows,keys,target);rows=rows.map(r=>({...r,...Object.fromEntries([...keys,target].map(k=>[k,Number(r[k])]))}));const start=performance.now(),random=rng(options.seed??42),count=Math.min(100,Math.max(1,options.trees??30)),depth=Math.min(5,Math.max(1,options.depth??3)),rate=Number(options.rate??.1);if(!(rate>0&&rate<=1))throw Error('学习率需大于0且不超过1');const fit={id,keys,target,trees:[],base:id==='boost'?avg(rows.map(r=>r[target])):0,rate,history:[]};let pred=rows.map(()=>fit.base);for(let i=0;i<count;i++){const data=id==='boost'?rows.map((r,j)=>({...r,__res:r[target]-pred[j]})):Array.from({length:rows.length},()=>rows[Math.floor(random()*rows.length)]);const subset=id==='forest'?[...keys].sort(()=>random()-.5).slice(0,Math.max(1,Math.ceil(Math.sqrt(keys.length)))):keys;const t=tree(data,subset,id==='boost'?'__res':target,depth,random);fit.trees.push(t);pred=id==='boost'?pred.map((p,j)=>p+rate*leaf(t,rows[j])):rows.map(r=>avg(fit.trees.map(t=>leaf(t,r))));fit.history.push({epoch:i+1,loss:avg(rows.map((r,j)=>(r[target]-pred[j])**2))});}return {...fit,duration:(performance.now()-start)/1000,trainedRows:rows.length};}
export const predictTrees=(fit,rows)=>rows.map(r=>{for(const k of fit.keys)numeric(r[k],k);return fit.id==='boost'?fit.base+fit.rate*fit.trees.reduce((s,t)=>s+leaf(t,r),0):avg(fit.trees.map(t=>leaf(t,r)));});
const harmonic=n=>n<=1?0:2*(Math.log(n-1)+.5772156649)-2*(n-1)/n;
function isolate(rows,keys,depth,random){if(rows.length<=1||depth<=0)return {n:rows.length};const active=keys.filter(k=>Math.max(...rows.map(r=>r[k]))>Math.min(...rows.map(r=>r[k])));if(!active.length)return {n:rows.length};const key=active[Math.floor(random()*active.length)],min=Math.min(...rows.map(r=>r[key])),max=Math.max(...rows.map(r=>r[key])),cut=min+random()*(max-min);return {key,cut,left:isolate(rows.filter(r=>r[key]<cut),keys,depth-1,random),right:isolate(rows.filter(r=>r[key]>=cut),keys,depth-1,random)};}
function path(t,r,d=0){return t.n!==undefined?d+harmonic(t.n):path(r[t.key]<t.cut?t.left:t.right,r,d+1);}
export function trainIsolation(rows,keys,options={}){validRows(rows,keys);const start=performance.now(),random=rng(options.seed??42),size=Math.min(rows.length,128),trees=[];for(let i=0;i<(options.trees??50);i++){const sample=[...rows];for(let j=sample.length-1;j>0;j--){const k=Math.floor(random()*(j+1));[sample[j],sample[k]]=[sample[k],sample[j]];}trees.push(isolate(sample.slice(0,size),keys,Math.ceil(Math.log2(size)),random));}const fit={id:'isolation',keys,trees,size,duration:(performance.now()-start)/1000,trainedRows:rows.length,history:[]};const scores=isolationScores(fit,rows).sort((a,b)=>a-b);fit.threshold=scores[Math.floor(.95*(scores.length-1))];return fit;}
export function isolationScores(fit,rows){for(const r of rows)for(const k of fit.keys)numeric(r[k],k);return rows.map(r=>2**(-avg(fit.trees.map(t=>path(t,r)))/harmonic(fit.size)));}
export function evolve(r,waterExposure){const e=nonnegative(waterExposure,'累计水洗倍数'),k=nonnegative(r.permeability,'初始渗透率'),phi=numeric(r.porosity,'孔隙度');return {permeability:k*(k>200?1+.12*Math.log1p(e):k<50?Math.exp(-.04*e):1-.08*e+.015*e*e),porosity:Math.max(.01,Math.min(.4,phi+.002*Math.log1p(e))),viscosity:nonnegative(r.viscosity,'黏度')*(1+.04*e),residualOil:Math.max(.08,Number(r.residualOil??.28)-.01*e)};}
// Transparent one-well finite-horizon MPC grid: scenario coefficients require field calibration.
export function mpc({injection,pressure,targetPressure,liquid,maxInjection,fracture,horizon=6,gain=.0003}){let best=null;for(let i=0;i<=80;i++){const u=maxInjection*i/80;let p=pressure,loss=0;const path=[];for(let h=0;h<horizon;h++){p+=gain*(u-liquid);loss+=(p-targetPressure)**2+.000001*(u-injection)**2;path.push(p);}if(path.some(p=>p>fracture))continue;if(!best||loss<best.loss)best={injection:u,loss,path};}if(!best)throw Error('当前压力约束下无可行调控方案');return best;}
export function differenceInDifferences({treatedBefore,treatedAfter,controlBefore,controlAfter}){return (numeric(treatedAfter,'措施组后期均值')-numeric(treatedBefore,'措施组前期均值'))-(numeric(controlAfter,'对照组后期均值')-numeric(controlBefore,'对照组前期均值'));}
export function assertExperimentWritable(s){if(s.busy)throw Error('模型正在训练，请等待完成后再修改或上传数据');}
export function toolEvidence(results,contexts={}){return Object.fromEntries(Object.entries(results).map(([k,result])=>[k,{result,context:contexts[k]??{source:'独立教学/手工输入情景，未绑定当前生产对象'},currentProductionEvidence:false}]));}
